```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate
WHERE {
  VALUES ?film { dbr:Three_Violent_People dbr:Girls_in_White }

  # director (prefer dbp:director, fallback to dbo:director)
  { ?film dbp:director ?director }
  UNION
  { ?film dbo:director ?director }

  # director's death date (prefer dbp:deathDate, fallback to dbo:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDate }
  OPTIONAL { ?director dbo:deathDate ?deathDate }
}
LIMIT 100
```

